/* The reader of the Fortress specification. The colours, the type sizes and the Select
   button come from the revival page (explorations/coordinator/process-engineering/
   revival-story.html); the fonts are the system's, since the reader loads nothing external. */
:root {
  --bg: #f6f7f6; --surface: #ffffff; --fg: #1d2421; --muted: #5b6661; --rule: #d8dedb;
  --accent: #1f6f5c; --code-bg: #eef1ef; --note-bg: #fbf4e4; --note-rule: #d9b45c;
  --rev-bg: #e9f0f8; --rev-rule: #1c548c; --rev-fg: #17446f; --mark: #fff3b8;
  --body: "Atkinson Hyperlegible", "Segoe UI", system-ui, -apple-system, sans-serif;
  --mono: "JetBrains Mono", ui-monospace, "SFMono-Regular", Menlo, Consolas, monospace;
  --math: "STIX Two Text", "STIXGeneral", "Times New Roman", Times, "Nimbus Roman", serif;
}
@media (prefers-color-scheme: dark) { :root:not([data-theme="light"]) {
  --bg: #141917; --surface: #1b211f; --fg: #e3e8e5; --muted: #9aa6a0; --rule: #2d3632;
  --accent: #6cc4a8; --code-bg: #222a27; --note-bg: #2a2518; --note-rule: #8a7333;
  --rev-bg: #18232f; --rev-rule: #6aa6de; --rev-fg: #9cc6ee; --mark: #4a431c; color-scheme: dark } }
:root[data-theme="dark"] {
  --bg: #141917; --surface: #1b211f; --fg: #e3e8e5; --muted: #9aa6a0; --rule: #2d3632;
  --accent: #6cc4a8; --code-bg: #222a27; --note-bg: #2a2518; --note-rule: #8a7333;
  --rev-bg: #18232f; --rev-rule: #6aa6de; --rev-fg: #9cc6ee; --mark: #4a431c; color-scheme: dark }

* { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; text-size-adjust: 100%; }
body { background: var(--bg); color: var(--fg); font-family: var(--body); font-size: 16px; line-height: 1.55;
  margin: 0; padding-inline: max(16px, env(safe-area-inset-left)) max(16px, env(safe-area-inset-right)); padding-block: 0 64px;
  overflow-wrap: break-word; }
.page { max-width: 46rem; margin: 0 auto; display: flex; flex-direction: column; gap: 24px; padding-top: 20px; }
.page > * { min-width: 0; }
